def sc(id, beat, narr, zh, en, cues, kws, view, tone, props, sources, track, tag, tagColor, status=None, statusAt=None, para=1):
    p = {"tag": tag, "tagColor": tagColor, "track": track, "kw": kws, "view": view, "tone": tone}
    if id == "s01": p["asOf"] = ASOF
    if status: p["status"] = status; p["statusAt"] = statusAt
    p.update(props)
    return {"id": id, "beat": beat, "narration": narr, "subtitle": {"zh": zh, "en": en}, "keywords": list(kws.keys()), "cues": [{"id": a, "text": b} for a, b in cues], "component": "IsoScene", "props": p, "sources": sources, "para": para}
